/* ScOperPrfmncMapper.upsertList */ MERGE INTO PMOWN.TN_PM_SC_OPER_PRFMNC A USING (
SELECT #{item.totDt} AS TOT_DT, #{item.tmnlId} AS TMNL_ID, #{item.depNum} AS DEP_NUM, #{item.scOperCnt} AS SC_OPER_CNT, #{item.scObsvCnt} AS SC_OBSV_CNT, #{item.wtngPsgCnt} AS WTNG_PSG_CNT FROM DUAL
) B ON ( A.TOT_DT = B.TOT_DT AND A.TMNL_ID = B.TMNL_ID AND A.DEP_NUM = B.DEP_NUM ) WHEN MATCHED THEN UPDATE SET A.SC_OPER_CNT = B.SC_OPER_CNT, A.SC_OBSV_CNT = B.SC_OBSV_CNT, A.WTNG_PSG_CNT = B.WTNG_PSG_CNT, A.LAST_MDFR_ID = #{regId}, A.LAST_MDFR_IP_ADDR = #{regIp}, A.LAST_MDFCN_DT = SYSTIMESTAMP WHEN NOT MATCHED THEN INSERT (TOT_DT, TMNL_ID, DEP_NUM, SC_OPER_CNT, SC_OBSV_CNT, WTNG_PSG_CNT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT) VALUES (B.TOT_DT, B.TMNL_ID, B.DEP_NUM, B.SC_OPER_CNT, B.SC_OBSV_CNT, B.WTNG_PSG_CNT, #{regId}, #{regIp}, SYSTIMESTAMP)
